package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import static com.aliothmoon.maafw.once.BingNavigationFixture.*;
import java.nio.file.*;
public class V46EntryMetadataTest {
 static String w(String component){return RootReadOnlyAnimationGuardTest.w().replace(BingNavigationSnapshot.TEMPLATE,component);}
 static String a(String component){return RootReadOnlyAnimationGuardTest.a().replace(BingNavigationSnapshot.TEMPLATE,component);}
 static BingNavigationSnapshot.Result r(String w,String a){return BingNavigationSnapshot.parseEntrySource(w,a,PROFILE,RootReadOnlyAnimationGuardTest.G,1000,1010);}
 @Test public void realMainIsOnlyNewEntryKind(){var x=r(w(BingNavigationSnapshot.MAIN),a(BingNavigationSnapshot.MAIN));assertEquals(BingNavigationSnapshot.Status.READY,x.status());assertEquals(BingNavigationSnapshot.Kind.MAIN,x.ready().kind());assertEquals("15",x.ready().task());assertEquals(BingNavigationSnapshot.Status.UNKNOWN,BingNavigationSnapshot.parseRootReadOnly(w(BingNavigationSnapshot.MAIN),a(BingNavigationSnapshot.MAIN),PROFILE,RootReadOnlyAnimationGuardTest.G,1000,1010).status());}
 @Test public void taskIsObservedNotOldScope(){String w=w(BingNavigationSnapshot.MAIN).replace("t15","t8").replace("rootTaskId=15","rootTaskId=8");String a=a(BingNavigationSnapshot.MAIN).replace("t15","t8").replace("#15","#8");assertEquals("8",r(w,a).ready().task());}
 @Test public void templateAcceptedBrowserUnknown(){assertEquals(BingNavigationSnapshot.Kind.TEMPLATE,r(w(BingNavigationSnapshot.TEMPLATE),a(BingNavigationSnapshot.TEMPLATE)).ready().kind());assertEquals(BingNavigationSnapshot.Status.UNKNOWN,r(w(BingNavigationSnapshot.BROWSER),a(BingNavigationSnapshot.BROWSER)).status());}
 @Test public void wrongMainSpellingCannotBecomeProof(){String c="com.microsoft.bing/com.microsoft.sapphire.app.main.SapphireMainActivity";assertEquals(BingNavigationSnapshot.Status.UNKNOWN,r(w(c),a(c)).status());}
 @Test public void requiresExactComponentTaskAndHiddenOwner(){assertNull(r(w(BingNavigationSnapshot.MAIN),a(BingNavigationSnapshot.TEMPLATE)).ready());assertNull(r(w(BingNavigationSnapshot.MAIN).replace("rootTaskId=15","rootTaskId=8"),a(BingNavigationSnapshot.MAIN)).ready());assertNull(r(w(BingNavigationSnapshot.MAIN).replace("mDrawState=NO_SURFACE","missing"),a(BingNavigationSnapshot.MAIN)).ready());}
 @Test public void sameSourceRequiresExactTokensButTransitionOnlySameTask(){var main=r(w(BingNavigationSnapshot.MAIN),a(BingNavigationSnapshot.MAIN)).ready();var same=r(w(BingNavigationSnapshot.MAIN),a(BingNavigationSnapshot.MAIN)).ready();var template=r(w(BingNavigationSnapshot.TEMPLATE),a(BingNavigationSnapshot.TEMPLATE)).ready();assertTrue(main.sameEntrySource(same));assertFalse(main.sameEntrySource(template));assertTrue(main.sameTask(template));var changed=r(w(BingNavigationSnapshot.MAIN).replace("Window{aaa u0","Window{abb u0"),a(BingNavigationSnapshot.MAIN)).ready();assertFalse(main.sameEntrySource(changed));}
 @Test public void staleAndUnboundedEvidenceRejected(){assertNull(BingNavigationSnapshot.parseEntrySource(w(BingNavigationSnapshot.MAIN),a(BingNavigationSnapshot.MAIN),PROFILE,RootReadOnlyAnimationGuardTest.G,1000,6001).ready());assertNull(r("x".repeat(262145),a(BingNavigationSnapshot.MAIN)).ready());}
 @Test public void stageBudgetsAreDisjointAndExhaustive(){int parent=0,helper=0;for(var stage:V46EntryMetadataReader.Stage.values()){boolean p=V46EntryMetadataReader.stageAllowed(false,stage),h=V46EntryMetadataReader.stageAllowed(true,stage);assertNotEquals(p,h);if(p)parent++;if(h)helper++;}assertEquals(7,parent);assertEquals(2,helper);assertFalse(V46EntryMetadataReader.stageAllowed(false,null));}
 @Test public void wrongBackendStageCannotInvokeProcess(){var app=V46EntryMetadataReader.app(PROFILE,RootReadOnlyAnimationGuardTest.G);assertNull(app.read(V46EntryMetadataReader.Stage.HELPER_PREPARE,10,()->true).ready());assertEquals(0,app.commandsInvoked());assertEquals(0,app.pairsUsed());var helper=V46EntryMetadataReader.rootHelper(PROFILE,RootReadOnlyAnimationGuardTest.G);assertNull(helper.read(V46EntryMetadataReader.Stage.ANCHOR,10,()->true).ready());assertEquals(0,helper.commandsInvoked());}
 @Test public void fixedCommandsAndCleanupRemainBounded()throws Exception{String s=Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once/V46EntryMetadataReader.java"));assertTrue(s.contains("new String[]{\"/system/bin/dumpsys\",\"window\",\"-a\"}"));assertTrue(s.contains("new String[]{\"/system/bin/dumpsys\",\"activity\",\"activities\"}"));assertTrue(s.contains("consumed.add(stage)"));assertTrue(s.contains("new byte[262144]"));assertTrue(s.contains("elapsedRealtime()+2000"));assertTrue(s.contains("Shizuku.getBinder()!=binder"));assertTrue(s.contains("clean=false;quarantine=true"));for(String bad:new String[]{"/system/bin/sh","System.out","Log.","writeString","getRootInActiveWindow","performAction"})assertFalse(bad,s.contains(bad));}
}
